// Keep the same six role positions even though passive structures omit drive/power/computer.
export function machineSlots(type){if(!Object.hasOwn(machineBlueprints,type))return [];return ['frame','fasteners','module','motion','power','computer'].filter(k=>machineBlueprints[type]?.slots[k]);}
