const clone=v=>JSON.parse(JSON.stringify(v));
function machineDraft(raw={},type=raw?.type,fill=false){raw=raw&&typeof raw==='object'?raw:{};if(!Object.hasOwn(machineBlueprints,type))return null;const d={type,color:Object.hasOwn(machineColors,raw.color)?raw.color:'blue',parts:{},editId:typeof raw.editId==='string'?raw.editId:null};for(const slot of machineSlots(type)){const options=machineBlueprints[type].slots[slot];if(options.includes(raw.parts?.[slot]))d.parts[slot]=raw.parts[slot];else if(fill)d.parts[slot]=options[0];}return d;}
export function machineReady(d){return !!d&&machineSlots(d.type).length>0&&machineSlots(d.type).every(k=>machineBlueprints[d.type].slots[k].includes(d.parts[k]));}
export function defaultMachines(){return {active:'rover',drafts:{},models:[],placements:[],history:[],service:{},serviced:[]};}
export function normalizeMachines(raw={}){const r=raw&&typeof raw==='object'?raw:{},s=defaultMachines();if(Object.hasOwn(machineBlueprints,r.active))s.active=r.active;for(const type of Object.keys(machineBlueprints))if(r.drafts?.[type])s.drafts[type]=machineDraft(r.drafts[type],type);for(const m of Array.isArray(r.models)?r.models:[]){if(s.models.length>=24)break;if(!m||!/^m[1-9]\d{0,5}$/.test(m.id)||s.models.some(x=>x.id===m.id))continue;const d=machineDraft(m,m.type,true);if(d)s.models.push({id:m.id,type:d.type,color:d.color,parts:d.parts});}for(const type of Object.keys(s.drafts))if(!s.models.some(m=>m.id===s.drafts[type].editId))s.drafts[type].editId=null;
 for(const p of Array.isArray(r.placements)?r.placements:[]){const site=Object.hasOwn(machineSites,p?.site)?machineSites[p.site]:null,model=s.models.find(m=>m.id===p?.modelId);if(!site||!model||!Number.isInteger(p.pad)||p.pad<0||p.pad>=site.pads.length||s.placements.some(x=>x.site===p.site&&x.pad===p.pad))continue;const snapshot=machineDraft(p.snapshot,model.type,true);if(!machinePadAllows(snapshot.type,p.site,p.pad))continue;s.placements.push({site:p.site,pad:p.pad,modelId:model.id,snapshot:{type:snapshot.type,color:snapshot.color,parts:snapshot.parts}});}
 for(const [id,checks]of Object.entries(r.service&&typeof r.service==='object'?r.service:{}))if(s.models.some(m=>m.id===id))s.service[id]=[...new Set((Array.isArray(checks)?checks:[]).filter(k=>['structure','drive','control'].includes(k)))];s.serviced=[...new Set((Array.isArray(r.serviced)?r.serviced:[]).filter(id=>s.models.some(m=>m.id===id)))];s.history=(Array.isArray(r.history)?r.history:[]).slice(-12).map(d=>machineDraft(d)).filter(Boolean);return s;}
export function machineName(m){return machineBlueprints[m.type].name+' '+m.id.slice(1);}
function machineRemember(s){const d=s.drafts[s.active];if(d){s.history.push(clone(d));if(s.history.length>12)s.history.shift();}}
export function machinePadAllows(type,site,pad){return Object.hasOwn(machineSites,site)&&machineSites[site].types.includes(type)&&Number.isInteger(pad)&&pad>=0&&pad<machineSites[site].pads.length&&(!(['chapterEarth','chapterMoon'].includes(site)&&['solar','rocket','airplane','drone'].includes(type))||pad===1);}
export function machineContextAllows(site,ctx={}){return site==='chapterMoon'?ctx.moonReady===true:site==='chapterEarth'?ctx.earthReady===true:true;}
export function machineCommand(raw,action,ctx={}){const s=normalizeMachines(raw);let route='home',message='',travel=null,effect=null;const d=()=>s.drafts[s.active]??=(machineDraft({},s.active));const model=()=>s.models.find(m=>m.id===action.id);
 if(action.type==='page')route=action.route;
 else if(action.type==='blueprint'&&Object.hasOwn(machineBlueprints,action.value)){s.active=action.value;const draft=d();if(draft.editId){machineRemember(s);draft.editId=null;}route='build:0';}
 else if(action.type==='part'){const draft=d(),options=machineBlueprints[draft.type].slots[action.slot]||[];if(options.includes(action.value)){machineRemember(s);draft.parts[action.slot]=action.value;message=machineParts[action.value].name+' fitted.';}route='build:'+Math.floor(Math.max(0,machineSlots(draft.type).indexOf(action.slot))/3);}
 else if(action.type==='helper'){const draft=d();machineRemember(s);for(const slot of machineSlots(draft.type))draft.parts[slot]??=machineBlueprints[draft.type].slots[slot][0];route='controls';message='PIP fitted the missing modules. Your choices stayed in place.';}
 else if(action.type==='color'&&Object.hasOwn(machineColors,action.value)){machineRemember(s);d().color=action.value;route='paint';}
 else if(action.type==='undo'){const old=s.history.pop();if(old){s.active=old.type;s.drafts[old.type]=old;}route='controls';}
 else if(action.type==='test'){route=machineReady(d())?'test':'controls';message=machineReady(d())?'It works! This compatible model uses your chosen parts.':'Choose the remaining modules, or let PIP fit them.';}
 else if(action.type==='save'){const draft=d();if(!machineReady(draft)){route='controls';message='PIP can help fit the remaining modules.';}else{let m=s.models.find(m=>m.id===draft.editId);if(!m&&s.models.length>=24){route='library:0';message='Your garage has 24 saved designs. Choose one to edit.';}else{if(!m){let i=1;while(s.models.some(m=>m.id==='m'+i))i++;m={id:'m'+i};s.models.push(m);}Object.assign(m,{type:draft.type,color:draft.color,parts:clone(draft.parts)});draft.editId=m.id;route='model:'+m.id;message='Saved in My Machines.';}}}
 else if(['edit','copy'].includes(action.type)&&model()){const m=model();s.active=m.type;machineRemember(s);s.drafts[m.type]=machineDraft({...m,editId:action.type==='edit'?m.id:null});route='build:0';}
 else if(action.type==='service'&&model()){const id=model().id;s.service[id]=[];route='service:'+id;}
 else if(action.type==='check'&&model()&&['structure','drive','control'].includes(action.value)){const id=model().id;s.service[id]??=[];if(!s.service[id].includes(action.value))s.service[id].push(action.value);if(s.service[id].length===3&&!s.serviced.includes(id))s.serviced.push(id);route='service:'+id;message=s.service[id].length===3?'Checked, repaired and ready. Your parts are unchanged.':'Module checked and adjusted.';}
 else if(action.type==='deploy'&&model()){const m=model(),site=machineSites[action.site];if(site&&machinePadAllows(m.type,action.site,action.pad)&&machineContextAllows(action.site,ctx)){const p={site:action.site,pad:action.pad,modelId:m.id,snapshot:{type:m.type,color:m.color,parts:clone(m.parts)}};const i=s.placements.findIndex(x=>x.site===p.site&&x.pad===p.pad);if(i<0)s.placements.push(p);else s.placements[i]=p;route='placed:'+p.site+':'+p.pad;message='Deployed! This copy keeps your selected parts.';}else{route='sites:'+m.id;message='Choose a compatible, available destination.';}}
 else if(action.type==='visit'&&Object.hasOwn(machineSites,action.site)&&machineContextAllows(action.site,ctx)){travel=action.site;route=action.pad===undefined?null:'placed:'+action.site+':'+action.pad;}
 else if(action.type==='use'){const p=s.placements.find(p=>p.site===action.site&&p.pad===action.pad);if(p){route='run:'+p.site+':'+p.pad;if(p.site==='farm'&&(p.snapshot.type==='rover'||p.snapshot.type==='helperbot'&&p.snapshot.parts.module==='sprayer'))effect='water-bed';if(p.site==='farm'&&p.snapshot.type==='solar')effect='farm-light';}}
 return {machines:s,route,message,travel,effect};}
