export function machineMotion(type,phase=0,reduced=false){const t=reduced?0.25:((phase%6)+6)%6/6,w=Math.sin(t*Math.PI*2),rise=(1-Math.cos(t*Math.PI*2))/2;return {x:['rover','helperbot','drone','submarine','airplane'].includes(type)?w*25:0,y:type==='rocket'?-rise*35:['drone','submarine','airplane'].includes(type)?-rise*12:0,cargoY:type==='crane'?-rise*35:0,helperX:40+t*260};}
